// Reading books: B's own plain-text books (data/books, generated by scripts/sync-books.mjs from the source folders).
// Library cards on the home page, a contents page and one shared reader (left contents, text, See also links,
// prev/next, bookmarks with notes, section progress). Sections are lazy-loaded one at a time. Reading state per
// book lives in study.reading[bookId] = { section, at, done: { [sectionId]: at }, marks: [{ section, note, at }] }
// and is exported/imported with the rest of the study data. Nothing here calls the tutor API.
const Shelf = (() => {
  let index = null; const tocs = {}, texts = {};
  const getJSON = async u => { const r = await fetch(u); if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); };
  const loadIndex = async () => index || (index = await getJSON('data/books/index.json'));
  const loadToc = async id => tocs[id] || (tocs[id] = await getJSON(`data/books/${id}/toc.json`));
  const loadText = async (id, s) => texts[`${id}/${s}`] || (texts[`${id}/${s}`] = await getJSON(`data/books/${id}/${s}.json`));
  const rs = id => (state.reading && state.reading[id]) || null;
  function update(id, fn) {
    const cur = rs(id) || { section: null, at: 0 }, next = fn(JSON.parse(JSON.stringify(cur)));
    if (!next.section) return;
    state.reading = { ...(state.reading || {}), [id]: next }; save();
  }
  const sections = toc => toc.chapters.flatMap(c => c.sections.filter(s => s.written).map(s => ({ ...s, ch: c })));
  const statusOf = (r, sid) => (r && r.done && r.done[sid] ? 'done' : r && r.section === sid ? 'reading' : 'new');
  const prog = (b, r) => { const done = r && r.done ? Object.keys(r.done).length : 0; return { done, total: b.sections, label: !r ? 'Not started' : done >= b.sections ? 'Completed' : 'In progress' }; };
  const fmtN = id => id.replace(/^0?(\d+)_0?(\d+)$/, '$1.$2');

  // ---- home library cards (added to the existing Library grid) ----
  async function mountHome() {
    let idx; try { idx = await loadIndex(); } catch (e) { return; }
    const grid = document.querySelector('main.page .grid'); if (!grid || grid.querySelector('.tb')) return;
    grid.insertAdjacentHTML('beforeend', idx.map(b => {
      const r = rs(b.id), p = prog(b, r);
      return `<a class="book tb" href="#/books/${b.id}${r ? '/' + r.section : ''}" data-shelf="${b.id}"><div class="book-title">${esc(b.title)}</div>
        <div class="book-meta">${esc(b.category)} · reading book${b.complete ? ' · complete' : ''}</div><div class="book-desc">${esc(b.subtitle)}</div>
        <div class="stats"><span><b>${b.chapters}</b> chapters</span><span><b>${b.sections}</b> sections</span><span><b>${Math.round(b.words / 1000)}k</b> words</span></div>
        <div class="prog${r ? ' on' : ''}">${r ? `${p.label} · ${p.done} of ${p.total} sections read · Continue: section ${fmtN(r.section)}` : 'Not started · Start reading'}</div>
        ${r ? `<div class="meter" aria-hidden="true"><span style="width:${(p.done / p.total) * 100}%"></span></div>` : ''}</a>`; }).join(''));
    const h = document.querySelector('main.page .section-h span:last-child'); if (h) h.textContent = plural(grid.querySelectorAll('.book').length, 'book');
  }
  function fail(msg, id) { renderMissing(msg, id ? `#/books/${id}` : '#/', id ? 'Back to contents' : 'Library'); }
  function switcher(idx, id) {
    return `<label class="sr" for="tb-switch">Switch book</label><select id="tb-switch" class="tb-switch">${idx.map(b => `<option value="#/books/${b.id}"${b.id === id ? ' selected' : ''}>${esc(b.title)}</option>`).join('')}<option value="#/book/heat-mass-transfer">Heat and Mass Transfer (study cards)</option></select>`;
  }
  function wireSwitch() { const s = document.getElementById('tb-switch'); if (s) s.onchange = () => { location.hash = s.value; }; }
  function navHTML(id, toc, r, curId) {
    return `<nav class="tb-side" id="tb-side" aria-label="Contents"><button type="button" class="btn ghost sm tb-close" id="tb-close">Close contents</button><ol>${toc.chapters.map(c => `<li${c.sections.some(s => s.id === curId) ? ' class="open"' : ''}><div class="tb-ch"><span>${c.n}</span>${esc(c.title)}</div><ol>${c.sections.map(s => s.written
      ? `<li><a href="#/books/${id}/${s.id}" class="st-${statusOf(r, s.id)}"${s.id === curId ? ' aria-current="page"' : ''}><span class="tb-n">${esc(s.n)}</span><span>${esc(s.title)}</span><i aria-label="${{ done: 'read', reading: 'in progress', new: 'not started' }[statusOf(r, s.id)]}"></i></a></li>`
      : `<li class="tb-todo"><span class="tb-n">${esc(s.n)}</span>${esc(s.title)} <em>missing</em></li>`).join('')}</ol></li>`).join('')}</ol></nav>`;
  }
  async function renderToc(id) {
    let toc, idx; try { idx = await loadIndex(); if (!idx.some(b => b.id === id)) return fail('There’s no book with that name.'); toc = await loadToc(id); } catch (e) { return fail('That book couldn’t be loaded.'); }
    document.title = `${toc.title} · LearnScroll`;
    const r = rs(id), all = sections(toc), cur = r && all.find(s => s.id === r.section), b = idx.find(x => x.id === id), p = prog(b, r);
    const marks = (r && r.marks) || [];
    app.innerHTML = `<main class="page tbpage"><div class="tb-top"><a class="back" href="#/">← Library</a>${switcher(idx, id)}</div>
      <div class="book-head"><div><h1>${esc(toc.title)}</h1><p class="meta-line">${esc(toc.category)} · ${b.chapters} chapters · ${b.sections} sections · ${p.label}${r ? ` (${p.done} of ${p.total} read)` : ''}</p><p class="tb-sub">${esc(toc.subtitle)}</p></div>
        ${all.length ? `<a class="btn" id="tb-go" href="#/books/${id}/${(cur || all[0]).id}">${cur ? `Continue: ${esc(cur.n)} ${esc(cur.title)}` : 'Start reading'}</a>` : ''}</div>
      <section class="tb-marks" aria-labelledby="tb-mh"><h2 id="tb-mh">Bookmarks</h2>${marks.length ? `<ul>${marks.map((m, i) => { const s = all.find(x => x.id === m.section);
        return `<li><a href="#/books/${id}/${m.section}">${s ? `${esc(s.n)} ${esc(s.title)}` : `Section ${esc(fmtN(m.section))} (no longer in the book)`}</a><label class="sr" for="tb-note-${i}">Note</label><textarea id="tb-note-${i}" data-note="${i}" rows="1" maxlength="1000" placeholder="Add a note">${esc(m.note || '')}</textarea><button class="t-link" data-unmark="${i}">Remove</button></li>`; }).join('')}</ul>` : '<p class="f-tag">No bookmarks yet. Use “Bookmark” while reading.</p>'}</section>
      <div class="tb-tocwrap">${navHTML(id, toc, r, cur && cur.id)}</div></main>`;
    wireSwitch();
    const main = app.querySelector('.tbpage');
    main.addEventListener('change', e => { const t = e.target.closest('[data-note]'); if (!t) return; const i = +t.dataset.note; update(id, x => { const m = x.marks[i]; if (m) { if (t.value.trim()) m.note = t.value.slice(0, 1000); else delete m.note; } return x; }); });
    main.addEventListener('click', e => { const t = e.target.closest('[data-unmark]'); if (!t) return; update(id, x => { x.marks.splice(+t.dataset.unmark, 1); if (!x.marks.length) delete x.marks; return x; }); renderToc(id); });
  }
  let current = null; // { id, sid, toc, text } for the tutor context
  async function renderSection(id, sid) {
    let toc, t, idx; try { idx = await loadIndex(); if (!idx.some(b => b.id === id)) return fail('There’s no book with that name.'); toc = await loadToc(id); } catch (e) { return fail('That book couldn’t be loaded.'); }
    const all = sections(toc), i = all.findIndex(s => s.id === sid);
    if (i < 0) return fail('That section isn’t in this book.', id);
    try { t = await loadText(id, sid); } catch (e) { return fail('That section couldn’t be loaded. Check your connection and try again.', id); }
    const s = all[i], prev = all[i - 1], next = all[i + 1];
    document.title = `${s.n} ${s.title} · ${toc.title}`;
    update(id, x => ({ ...x, section: sid, at: Date.now() }));
    const r = rs(id), b = idx.find(x => x.id === id), p = prog(b, r), marked = ((r && r.marks) || []).some(m => m.section === sid);
    current = { id, sid, toc, section: s, text: t.text };
    const nav = `<nav class="tb-nav" aria-label="Previous and next section">${prev ? `<a class="btn ghost" href="#/books/${id}/${prev.id}" rel="prev" id="tb-prev">← ${esc(prev.n)} ${esc(prev.title)}</a>` : '<span class="f-tag">Start of the book</span>'}${next ? `<a class="btn ghost" href="#/books/${id}/${next.id}" rel="next" id="tb-next">${esc(next.n)} ${esc(next.title)} →</a>` : '<span class="f-tag">End of the book</span>'}</nav>`;
    app.innerHTML = `<main class="page tbpage tbread"><div class="tb-bar"><a class="back" href="#/books/${id}">← Book</a><button class="t-link tb-menu" id="tb-menu" aria-controls="tb-side" aria-expanded="false">Sections</button>${switcher(idx, id)}
        <span class="tb-prog" id="tb-prog">${p.done} of ${p.total} read</span><button class="btn ghost sm" id="tb-mark" aria-pressed="${marked}">${marked ? 'Bookmarked' : 'Bookmark'}</button></div>
      <div class="tb-layout">${navHTML(id, toc, r, sid)}
      <article class="tb-art" lang="en"><div class="tb-where">${esc(toc.title)} · Chapter ${s.ch.n}: ${esc(s.ch.title)} · Section ${esc(s.n)}</div>${BookText.html(t.text)}<div id="tb-end"></div>${nav}</article></div></main>`;
    wireSwitch();
    const side = document.getElementById('tb-side'), menu = document.getElementById('tb-menu');
    menu.onclick = () => { const o = !document.body.classList.contains('tb-nav-open'); document.body.classList.toggle('tb-nav-open', o); menu.setAttribute('aria-expanded', String(o)); if (o) { const a = side.querySelector('[aria-current]'); (a || side.querySelector('a')).focus(); } };
    side.addEventListener('click', e => { if (e.target.closest('a, #tb-close')) { document.body.classList.remove('tb-nav-open'); menu.setAttribute('aria-expanded', 'false'); if (e.target.id === 'tb-close') menu.focus(); } });
    const cur = side.querySelector('[aria-current]'); if (cur && window.innerWidth > 900) cur.scrollIntoView({ block: 'center' });
    window.scrollTo(0, 0);
    document.getElementById('tb-mark').onclick = () => {
      update(id, x => { const ms = x.marks || [], k = ms.findIndex(m => m.section === sid); if (k >= 0) ms.splice(k, 1); else ms.push({ section: sid, at: Date.now() }); if (ms.length) x.marks = ms; else delete x.marks; return x; });
      const on = rs(id).marks && rs(id).marks.some(m => m.section === sid), bt = document.getElementById('tb-mark'); bt.setAttribute('aria-pressed', String(!!on)); bt.textContent = on ? 'Bookmarked' : 'Bookmark';
    };
    // Section progress: read once its end has been on screen (after a short delay so a fast scroll past doesn't count).
    let tm = null;
    const io = new IntersectionObserver(es => { if (es.some(e => e.isIntersecting)) { tm = setTimeout(() => { update(id, x => ({ ...x, done: { ...(x.done || {}), [sid]: x.done && x.done[sid] || Date.now() } })); const pp = prog(b, rs(id)); const el = document.getElementById('tb-prog'); if (el) el.textContent = `${pp.done} of ${pp.total} read`; const a = side.querySelector('[aria-current]'); if (a) a.className = 'st-done'; }, 800); } else clearTimeout(tm); });
    io.observe(document.getElementById('tb-end'));
    const onKey = e => { if (e.target.closest('input,textarea,select') || e.altKey || e.ctrlKey || e.metaKey) return; if (e.key === 'Escape') document.body.classList.remove('tb-nav-open'); if (e.key === 'ArrowLeft' && prev) location.hash = `#/books/${id}/${prev.id}`; if (e.key === 'ArrowRight' && next) location.hash = `#/books/${id}/${next.id}`; };
    document.addEventListener('keydown', onKey);
    cleanup = () => { document.removeEventListener('keydown', onKey); io.disconnect(); clearTimeout(tm); document.body.classList.remove('tb-nav-open'); current = null; };
  }
  function route(parts) { if (!parts[1]) return go('#/'); if (!/^[a-z0-9-]{1,40}$/.test(parts[1])) return fail('Unknown book.'); if (parts[2] && !/^\d{2}_\d{2}$/.test(parts[2])) return fail('That section isn’t in this book.', parts[1]); return parts[2] ? renderSection(parts[1], parts[2]) : renderToc(parts[1]); }
  return { route, mountHome, loadIndex, current: () => current };
})();
if (typeof module !== 'undefined') module.exports = Shelf;
